import limited_client as robot, numpy as np
from PIL import Image
from scipy import ndimage
for c in (2,0):
 o=robot.observe(camera=c); Image.fromarray(o['rgb']).save(f'/app/output/relocalized147_{c}.png')
 print('CAM',c,'ROBOT',o['robot'])
 if c==2:
  rgb=o['rgb'].astype(int); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
  p=np.linalg.inv(T)@np.array(o['robot']['tcp_position']+[1.]); uv=K@p[:3]
  print('TCP_PIXEL',(uv[:2]/uv[2]).round(1).tolist(),'CAMXYZ',p[:3].round(3).tolist())
  for v in (420,430,440,450,455,460,465,470,480):
   if v<480: print('ROW',v,[(u,rgb[v,u].tolist(),round(float(d[v,u]),3)) for u in (120,140,155,165,175,190,210)])
  mask=(rgb[:,:,0]>rgb[:,:,1]+10)&(rgb[:,:,2]>rgb[:,:,1]+5)&(rgb[:,:,0]>40)&(d>0)
  lab,n=ndimage.label(mask)
  for i in range(1,n+1):
   y,x=np.where(lab==i)
   if len(x)>8: print('PURPLE',(int(x.min()),int(x.max()),int(y.min()),int(y.max())),len(x))
print('STATUS',robot.status())
